function mergeBlocked(pr, repo) {
    const rule = protectionFor(repo.id, pr.base);
    if (hasRequestChanges(pr)) return 'Changes requested';
    if (rule && rule.requireApproval && approvalCount(pr) < 1) return 'Review required by branch protection';
    if (rule && rule.requireCheck) {
      const chk = (st().checks || []).find((c) => c.prId === pr.id && c.name === 'test');
      if (!chk || chk.status !== 'success') return 'Required check test is not success';
    }
    return null;
  }

function protectionFor(repoId, branch) {
    return (st().protectionRules || []).find((r) => r.repoId === repoId && r.branch === branch) || null;
  }

function hasRequestChanges(pr) {
    const seen = {};
    for (const rv of st().reviews || []) { if (rv.prId === pr.id) seen[rv.reviewer] = rv; }
    return Object.keys(seen).some((k) => seen[k].state === 'Changes requested');
  }

