function compareScreen(repo) {
    const ui = UI();
    const key = 'compare:' + repo.id;
    const cmp = ui[key] || { base: repo.defaultBranch, compare: ui['branch:' + repo.id] || repo.defaultBranch };
    const names = branchNames(repo.id);
    const same = cmp.base === cmp.compare;
    const changed = same ? [] : changedBetween(repo, cmp.base, cmp.compare);
    const u = ARC.currentUser();
    const canCreate = !!u && atLeast(repo, u, 'Write');
    const open = ui['createPr:' + repo.id];
    const draftOpen = ui['createDraft:' + repo.id];
    return '<h1>' + esc(repoLabel(repo)) + '</h1>' + repoNav(repo, 'Pull requests') +
      '<h2>Compare changes</h2>' +
      '<p class="branch-pair"><span class="branch-pill">' + esc(cmp.base) + '</span> <span class="branch-pill">' + esc(cmp.compare) + '</span></p>' +
      '<form data-action="compare-branches" data-id="' + esc(repo.id) + '">' +
      '<label for="cmp-base">base</label><select id="cmp-base" name="base" aria-label="base" data-change="compare-live">' +
      names.map((n) => '<option value="' + esc(n) + '"' + (cmp.base === n ? ' selected' : '') + '>' + esc(n) + '</option>').join('') + '</select>' +
      '<label for="cmp-compare">compare</label><select id="cmp-compare" name="compare" aria-label="compare" data-change="compare-live">' +
      names.map((n) => '<option value="' + esc(n) + '"' + (cmp.compare === n ? ' selected' : '') + '>' + esc(n) + '</option>').join('') + '</select>' +
      '<button type="submit">Compare changes</button>' +
      '</form>' +
      (same
        ? '<p class="empty">No changes</p>'
        : '<section class="compare-result"><h3>Changed files</h3>' +
          changed.map((f) => '<article class="row changed-file" data-id="' + esc(f.path) + '">' +
            '<p class="file-path">' + esc(f.path) + '</p>' +
            '<p class="line-count">' + (f.additions || 0) + ' additions, ' + (f.deletions || 0) + ' deletions</p></article>').join('') +
          '<p class="commit-summary"><span class="commit-summary-label">Commit summary</span> <span class="commit-summary-count">' + changed.length + '</span></p></section>') +
      (canCreate && !same
        ? (open
          ? '<form data-action="create-pr" data-id="' + esc(repo.id) + '" data-base="' + esc(cmp.base) + '" data-compare="' + esc(cmp.compare) + '">' +
            '<label for="pr-title">Title</label><input id="pr-title" name="title" type="text" placeholder="Title" aria-label="Title">' +
            '<label for="pr-body">Description</label><textarea id="pr-body" name="body" placeholder="Description" aria-label="Description"></textarea>' +
            '<button type="submit">Create pull request</button></form>'
          : draftOpen
            ? '<form data-action="create-draft" data-id="' + esc(repo.id) + '" data-base="' + esc(cmp.base) + '" data-compare="' + esc(cmp.compare) + '">' +
              '<label for="prd-title">Title</label><input id="prd-title" name="title" type="text" placeholder="Title" aria-label="Title">' +
              '<label for="prd-body">Description</label><textarea id="prd-body" name="body" placeholder="Description" aria-label="Description"></textarea>' +
              '<button type="submit">Create draft pull request</button></form>'
            : '<p><button type="button" data-action="open-create-pr" data-id="' + esc(repo.id) + '">Create pull request</button> ' +
              '<button type="button" data-action="open-create-draft" data-id="' + esc(repo.id) + '">Create draft pull request</button></p>')
        : '<p><button type="button" disabled>Create pull request</button></p>');
  }

function changedBetween(repo, base, compare) {
    const headC = commitChain(repo.id, branchHead(repo.id, compare));
    const baseC = commitChain(repo.id, branchHead(repo.id, base));
    const baseIds = baseC.map((c) => c.id);
    const out = {};
    headC.forEach((c) => {
      if (baseIds.indexOf(c.id) !== -1) return;
      (c.files || []).forEach((f) => {
        if (!out[f.path]) out[f.path] = { path: f.path, additions: 0, deletions: 0 };
        out[f.path].additions += f.additions || 0;
        out[f.path].deletions += f.deletions || 0;
      });
    });
    return Object.keys(out).map((k) => out[k]);
  }

function createPull(ctx, state) {
    const repo = byId('repositories', ctx.el.dataset.id);
    const u = ARC.currentUser();
    const title = String(ctx.form.title || '').trim();
    if (!title) { ARC.notify('Title is required'); return; }
    if (title.length > 256) { ARC.notify('Title is too long'); return; }
    const number = Math.max(0, ...(st().pulls || []).filter((p) => p.repoId === repo.id).map((p) => p.number)) + 1;
    const base = ctx.el.dataset.base || repo.defaultBranch;
    const compare = ctx.el.dataset.compare || repo.defaultBranch;
    const changed = changedBetween(repo, base, compare);
    const pr = {
      id: uid('p'), repoId: repo.id, number: number, title: title, author: u.username,
      base: base, compare: compare, state: state, body: ctx.form.body || '',
      createdAt: nowIso(), changedFiles: changed
    };
    st().pulls.push(pr);
    ARC.save();
    UI()['createPr:' + repo.id] = false;
    UI()['createDraft:' + repo.id] = false;
    ARC.navigate(repoUrl(repo) + '/pull/' + number);
  }

function commitChain(repoId, headId) {
    const out = [];
    const guard = {};
    let id = headId;
    while (id && !guard[id]) {
      guard[id] = true;
      const c = byId('commits', id);
      if (!c) break;
      out.push(c);
      id = c.parent;
    }
    return out;
  }

function branchHead(repoId, branch) {
    const b = (st().branches || []).find((x) => x.repoId === repoId && x.name === branch);
    return b ? b.commitId : null;
  }

function branchNames(repoId) {
    return (st().branches || []).filter((b) => b.repoId === repoId).map((b) => b.name);
  }

function atLeast(repo, user, level) {
    const r = roleFor(repo, user);
    return !!r && RANK[r] >= RANK[level];
  }

function roleFor(repo, user) {
    if (!repo || !user) return null;
    if (repo.ownerType === 'user') return repo.ownerId === user.id ? 'Admin' : directRole(repo, user, null);
    const org = orgFor(repo);
    if (!org) return directRole(repo, user, null);
    const m = orgMemberOf(org.id, user.id);
    if (m && m.role === 'Owner') return 'Admin';
    return directRole(repo, user, org.id);
  }

function orgMemberOf(orgId, userId) {
    return (st().orgMembers || []).find((m) => m.orgId === orgId && m.userId === userId) || null;
  }

function directRole(repo, user, orgId) {
    let best = null;
    const teams = orgId ? teamIdsFor(user.id, orgId) : [];
    for (const g of st().grants || []) {
      if (g.repoId !== repo.id) continue;
      const match = (g.kind === 'user' && g.subjectId === user.id) || (g.kind === 'team' && teams.indexOf(g.subjectId) !== -1);
      if (match && (!best || RANK[g.role] > RANK[best])) best = g.role;
    }
    return best;
  }

function teamIdsFor(userId, orgId) {
    return (st().teamMembers || [])
