      ['Code', (active === 'Code' && codeHref) ? codeHref : base],
      ['Issues', base + '/issues'],
      ['Pull requests', base + '/pulls'],
      ['Settings', base + '/settings']
    ];
    return '<nav class="repo-nav">' + items.map(function (i) {
      return '<a href="' + i[1] + '"' + (active === i[0] ? ' aria-current="page"' : '') + '>' + i[0] + '</a>';
