function prScreen(repo, num, tab) {
    const pr = (st().pulls || []).find((p) => p.repoId === repo.id && String(p.number) === String(num));
    if (!pr) return '<h1>Pull request not found</h1>';
    const u = ARC.currentUser();
    const base = repoUrl(repo) + '/pull/' + pr.number;
    const active = tab || 'conversation';
    const canClose = !!u && (u.username === pr.author || atLeast(repo, u, 'Maintain') || atLeast(repo, u, 'Admin'));
    const canReview = !!u && u.username !== pr.author && pr.state === 'Open' && atLeast(repo, u, 'Write');
    const blocked = mergeBlocked(pr, repo);
    const ui = UI();
    const changed = pr.changedFiles || [];
    const additions = changed.reduce((n, f) => n + (f.additions || 0), 0);
    const deletions = changed.reduce((n, f) => n + (f.deletions || 0), 0);
    const chain = commitChain(repo.id, branchHead(repo.id, pr.compare));
    const reviews = (st().reviews || []).filter((r) => r.prId === pr.id);
    const requests = (st().reviewerRequests || []).filter((r) => r.prId === pr.id);
    const reviewerOpen = ui['reviewers:' + pr.id];
    const reviewerQ = ui['reviewersQ:' + pr.id] || '';
    const lineOpen = ui['line:' + pr.id];
    const reviewOpen = ui['review:' + pr.id];
    const candidates = (st().users || []).filter((x) => x.username !== pr.author && atLeast(repo, x, 'Write'))
      .filter((x) => !reviewerQ || x.username.toLowerCase().indexOf(reviewerQ.toLowerCase()) !== -1);

    const nav = '<nav class="pr-nav">' +
      ['Conversation', 'Commits', 'Files changed', 'Checks'].map((t) => {
        const slug = t === 'Conversation' ? 'conversation' : t === 'Commits' ? 'commits' : t === 'Files changed' ? 'files' : 'checks';
        return '<a href="' + base + (slug === 'conversation' ? '' : '/' + slug) + '"' + (active === slug ? ' aria-current="page"' : '') + '>' + t + '</a>';
      }).join('') + '</nav>';

    let body = '';
    if (active === 'commits') {
      body = '<h2>Commits</h2><p class="commit-summary"><span class="commit-summary-label">Commit summary</span> <span class="commit-summary-count">' + chain.length + '</span></p>' +
        chain.map((c) => '<article class="row commit-row" data-id="' + esc(c.id) + '">' +
          '<h3>' + esc(c.sha) + '</h3><p>' + esc(c.message) + '</p><p>' + esc(c.author) + '</p></article>').join('');
    } else if (active === 'files') {
      body = '<h2>Changed files</h2>' +
        '<p class="diff-summary">' + additions + ' additions, ' + deletions + ' deletions</p>' +
        '<p class="hint">' + esc('Aggregate format: <addition count> additions, <deletion count> deletions') + '</p>' +
        changed.map((f) => '<article class="row changed-file" data-id="' + esc(f.path) + '">' +
          '<p class="file-path">' + esc(f.path) + '</p>' +
          '<p class="line-count">' + (f.additions || 0) + ' additions, ' + (f.deletions || 0) + ' deletions</p>' +
          (lineOpen === f.path
            ? '<form data-action="add-single-comment" data-id="' + esc(pr.id) + '" data-path="' + esc(f.path) + '">' +
              '<textarea name="body" aria-label="Comment" placeholder="Comment"></textarea>' +
              '<button type="submit">Add single comment</button>' +
              '<button type="button" data-action="start-review" data-id="' + esc(pr.id) + '" data-path="' + esc(f.path) + '">Start a review</button></form>'
            : '') +
          ((st().reviewComments || []).filter((c) => c.prId === pr.id && c.path === f.path).map((c) =>
            '<div class="inline-comment"><p>' + esc(c.author) + '</p><p>' + esc(c.body) + '</p>' +
            (c.published ? '' : '<p class="pending">Pending review</p>') + '</div>').join('')) +
          (canReview
            ? '<button type="button" data-action="open-line-comment" data-id="' + esc(pr.id) + '" data-path="' + esc(f.path) + '" aria-label="Add comment">+</button>'
            : '') +
          '</article>').join('');
      body += canReview && !reviewOpen
        ? '<p><button type="button" data-action="open-review" data-id="' + esc(pr.id) + '">Review changes</button></p>'
        : '';
      if (canReview && reviewOpen) {
        body += '<form data-action="submit-review" data-id="' + esc(pr.id) + '">' +
          '<label for="rv-summary">Summary</label><textarea id="rv-summary" name="summary" placeholder="Summary" aria-label="Summary"></textarea>' +
          '<label><input type="radio" name="state" value="Comment"> Comment</label>' +
          '<label><input type="radio" name="state" value="Approve"> Approve</label>' +
          '<label><input type="radio" name="state" value="Request changes"> Request changes</label>' +
          '<button type="submit">Submit review</button></form>';
      }
    } else if (active === 'checks') {
      body = checksBox(repo, pr);
    } else {
      body = '<h2>Conversation</h2>' +
        '<p class="pr-body">' + esc(pr.body || '') + '</p>' +
        '<p class="pr-branches"><span class="branch-pill">' + esc(pr.compare) + '</span> → <span class="branch-pill">' + esc(pr.base) + '</span></p>' +
        chain.map((c) => '<article class="row commit-row" data-id="' + esc(c.id) + '"><p>' + esc(c.message) + '</p></article>').join('') +
        reviews.map((r) => '<article class="row review-row" data-id="' + esc(r.id) + '">' +
          '<p class="review-state">' + esc(r.state) + '</p><p>' + esc(r.reviewer) + '</p><p>' + esc(r.body || '') + '</p></article>').join('') +
        checksBox(repo, pr);
    }

    return '<h1>' + esc(pr.title) + '</h1>' +
      '<p class="pr-number">#' + pr.number + '</p>' +
      '<p class="pr-state">' + esc(pr.state) + '</p>' +
      (pr.state === 'Draft' ? '<p class="draft-badge">Draft</p>' : '') +
      repoNav(repo, 'Pull requests') + nav +
      '<div class="pr-main">' + body + '</div>' +
      '<aside class="pr-sidebar">' +
      '<h2>Reviewers</h2>' +
      '<p class="field-note">reviewer request</p><p class="field-note">PR-reviewer request</p>' +
      requests.map((r) => '<article class="row reviewer-row" data-id="' + esc(r.id) + '">' +
        '<p>' + esc(r.username) + '</p>' +
        (canClose ? '<button type="button" data-action="remove-reviewer" data-id="' + esc(r.id) + '">Remove ' + esc(r.username) + '</button>' : '') +
        '</article>').join('') +
      (canClose
        ? (reviewerOpen
          ? '<div class="picker"><input type="text" aria-label="Search" placeholder="Search" data-change="reviewer-search" data-id="' + esc(pr.id) + '" value="' + esc(reviewerQ) + '">' +
            candidates.map((x) => '<span role="option" tabindex="-1" data-action="pick-reviewer" data-id="' + esc(pr.id) + '" data-user="' + esc(x.username) + '">' + esc(x.username) + '</span>').join('') + '</div>'
          : '<button type="button" data-action="open-reviewers" data-id="' + esc(pr.id) + '">Reviewers</button>')
        : '') +
      '<h2>Merge</h2>' +
      '<label><input type="radio" name="mergeMethod" value="Create a merge commit" checked> Create a merge commit</label>' +
      '<p class="merge-reason">' + esc(blocked || '') + '</p>' +
      (pr.state === 'Draft'
        ? '<p><button type="button" disabled>Merge pull request</button></p>' +
          (u && (u.username === pr.author || atLeast(repo, u, 'Maintain') || atLeast(repo, u, 'Admin'))
            ? '<p><button type="button" data-action="ready-for-review" data-id="' + esc(pr.id) + '">Ready for review</button></p>'
            : '')
        : (pr.state === 'Open'
          ? '<p><button type="button" data-action="open-merge" data-id="' + esc(pr.id) + '"' + (blocked ? ' disabled' : '') + '>Merge pull request</button></p>' +
            '<p><button type="button" data-action="confirm-merge" data-id="' + esc(pr.id) + '"' + (blocked ? ' disabled' : '') + '>Confirm merge</button></p>'
          : '')) +
      (canClose && pr.state !== 'Merged'
        ? (pr.state === 'Closed' || pr.state === 'Draft'
          ? '<p><button type="button" data-action="reopen-pr" data-id="' + esc(pr.id) + '">Reopen pull request</button></p>'
          : '<p><button type="button" data-action="close-pr" data-id="' + esc(pr.id) + '">Close pull request</button></p>')
        : '') +
      '</aside>';
  }

function mergeBlocked(pr, repo) {
    const rule = protectionFor(repo.id, pr.base);
    if (hasRequestChanges(pr)) return 'Changes requested';
    if (rule && rule.requireApproval && approvalCount(pr) < 1) return 'Review required by branch protection';
    if (rule && rule.requireCheck) {
      const chk = (st().checks || []).find((c) => c.prId === pr.id && c.name === 'test');
      if (!chk || chk.status !== 'success') return 'Required check test is not success';
    }
    return null;
  }

function protectionFor(repoId, branch) {
    return (st().protectionRules || []).find((r) => r.repoId === repoId && r.branch === branch) || null;
  }

function hasRequestChanges(pr) {
    const seen = {};
    for (const rv of st().reviews || []) { if (rv.prId === pr.id) seen[rv.reviewer] = rv; }
    return Object.keys(seen).some((k) => seen[k].state === 'Changes requested');
  }

function approvalCount(pr) {
    // A review decision is only valid for the CURRENT compare commit: when the compare branch gains a
    // new commit every earlier decision becomes stale and a fresh non-author Approve is required.
    const head = branchHead(pr.repoId, pr.compare);
    const seen = {};
    if (!head) return 0;
    for (const rv of st().reviews || []) {
      if (rv.prId !== pr.id) continue;
      seen[rv.reviewer] = rv;
    }
    let n = 0;
    Object.keys(seen).forEach((k) => {
      const rv = seen[k];
      if (rv.state !== 'Approved' || rv.reviewer === pr.author) return;
      if (rv.commitId !== head) return;
      n += 1;
    });
    return n;
  }

function branchHead(repoId, branch) {
    const b = (st().branches || []).find((x) => x.repoId === repoId && x.name === branch);
    return b ? b.commitId : null;
  }

function commitChain(repoId, headId) {
    const out = [];
    const guard = {};
    let id = headId;
    while (id && !guard[id]) {
      guard[id] = true;
      const c = byId('commits', id);
      if (!c) break;
      out.push(c);
      id = c.parent;
    }
    return out;
  }

function atLeast(repo, user, level) {
    const r = roleFor(repo, user);
    return !!r && RANK[r] >= RANK[level];
  }

function roleFor(repo, user) {
    if (!repo || !user) return null;
    if (repo.ownerType === 'user') return repo.ownerId === user.id ? 'Admin' : directRole(repo, user, null);
    const org = orgFor(repo);
    if (!org) return directRole(repo, user, null);
    const m = orgMemberOf(org.id, user.id);
    if (m && m.role === 'Owner') return 'Admin';
    return directRole(repo, user, org.id);
  }

function orgMemberOf(orgId, userId) {
    return (st().orgMembers || []).find((m) => m.orgId === orgId && m.userId === userId) || null;
  }

function directRole(repo, user, orgId) {
    let best = null;
    const teams = orgId ? teamIdsFor(user.id, orgId) : [];
    for (const g of st().grants || []) {
      if (g.repoId !== repo.id) continue;
      const match = (g.kind === 'user' && g.subjectId === user.id) || (g.kind === 'team' && teams.indexOf(g.subjectId) !== -1);
      if (match && (!best || RANK[g.role] > RANK[best])) best = g.role;
    }
    return best;
  }

function teamIdsFor(userId, orgId) {
    return (st().teamMembers || [])
      .filter((m) => m.userId === userId && ((byId('teams', m.teamId) || {}).orgId === orgId))
      .map((m) => m.teamId);
  }

function checksBox(repo, pr) {
    const u = ARC.currentUser();
    const chk = (st().checks || []).find((c) => c.prId === pr.id && c.name === 'test') || { status: 'pending' };
    const admin = atLeast(repo, u, 'Admin');
    return '<section class="checks">' +
      '<h2>Check results</h2>' +
      '<p class="check-line">test: ' + esc(chk.status) + '</p>' +
      (chk.setter ? '<p class="check-meta">Set by ' + esc(chk.setter) + ' at ' + esc(chk.time) + '</p>' : '') +
      '<p class="rule-desc">required check test is success</p>' +
      (admin
        ? '<form data-action="save-check" data-id="' + esc(pr.id) + '">' +
          ARC.combobox({ label: 'test status', name: 'status', options: ['pending', 'success', 'failure'], value: 'success' }) +
          ' <button type="submit">Save</button></form>'
        : '') +
      '</section>';
  }

function repoNav(repo, active, codeHref) {
    const base = repoUrl(repo);
    const items = [
      ['Code', (active === 'Code' && codeHref) ? codeHref : base],
      ['Issues', base + '/issues'],
      ['Pull requests', base + '/pulls'],
      ['Settings', base + '/settings']
    ];
    return '<nav class="repo-nav">' + items.map(function (i) {
      return '<a href="' + i[1] + '"' + (active === i[0] ? ' aria-current="page"' : '') + '>' + i[0] + '</a>';
    }).join('') + '</nav>';
  }

