bindings.setup:
window.ARC = window.ARC || {};
ARC.state = window.SEED;
ARC.esc = function (s) { return String(s == null ? '' : s); };
ARC.uid = function (p) { return p + '-' + Math.random().toString(36).slice(2, 8); };
ARC.save = function () {};
ARC.render = function () {};
ARC.navigate = function () {};
ARC.notify = function () {};
ARC.openDialog = function () {};
ARC.closeDialog = function () {};
ARC.openPopover = function () {};
ARC.closePopover = function () {};
ARC.combobox = function () { return ''; };
ARC.route = function () { return { name: 'repo', params: [] }; };
ARC.currentUser = function () { var s = window.SEED.session; return (window.SEED.users || []).filter(function (u) { return u.id === s; })[0] || null; };
ARC.state.session = 'u1';
ARC.state.ui = ARC.state.ui || {};

bindings.precondition:
var u = ARC.currentUser();
assert.ok(u);
assert.strictEqual(u.username, 'alice-dev');
var repo = ARC.state.repositories.filter(function (r) { return r.id === 'r1'; })[0];
assert.ok(repo);
var p1 = ARC.state.pulls.filter(function (p) { return p.repoId === 'r1' && String(p.number) === '1'; })[0];
var p3 = ARC.state.pulls.filter(function (p) { return p.repoId === 'r1' && String(p.number) === '3'; })[0];
assert.strictEqual(p1.state, 'Open');
assert.strictEqual(p1.author, 'alice-dev');
assert.strictEqual(p3.state, 'Draft');
assert.strictEqual(p3.author, 'alice-dev');

bindings.check:
var repo = ARC.state.repositories.filter(function (r) { return r.id === 'r1'; })[0];
var openHtml = prScreen(repo, 1, 'conversation');
assert.ok(openHtml.indexOf('Close pull request') !== -1, 'control: an Open PR authored by the signed-in user offers Close pull request');
var draftHtml = prScreen(repo, 3, 'conversation');
assert.ok(draftHtml.indexOf('Close pull request') !== -1, 'the author of an unmerged Draft PR must be able to close it, so Close pull request must be present');
